package com.stocksense.inventory.receipt; import com.stocksense.inventory.stock.StockService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.Map; @RestController @RequestMapping("/api/receipts") @RequiredArgsConstructor public class ReceiptController { private final StockService stock; record Req(Long productId,Long locationId,BigDecimal quantity,String supplier){} @PostMapping("/validate") public Map<String,Object> validate(@RequestBody Req r,Authentication a){stock.receive(r.productId(),r.locationId(),r.quantity(),a.getName());return Map.of("status","DONE","message","Receipt validated; stock increased");} }
